// Generates the demo catalogue photos as flat, neutral still-life illustrations (no third-party assets):
// a warm off-white backdrop with one simple silhouette per product. Output: seed/images/*.jpg, 1200×1200.
// Licence: CC0 — generated by this script, do whatever you like with them.
//   node seed/demo-images.mjs
import { mkdirSync, writeFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"
import sharp from "sharp"

const out = join(dirname(fileURLToPath(import.meta.url)), "images")
mkdirSync(out, { recursive: true })

const BG = ["#F3F0EA", "#EEEBE6", "#F5F2EC", "#ECE9E3"]
const INK = ["#2A2724", "#4A443E", "#6B645C", "#8A8178", "#B5ADA3"]
const shapes = {
  plate: (c) => `<circle cx="600" cy="600" r="330" fill="${c}"/><circle cx="600" cy="600" r="230" fill="none" stroke="#F3F0EA" stroke-opacity=".35" stroke-width="6"/>`,
  bowl: (c) => `<path d="M270 540 h660 a330 330 0 0 1 -660 0z" fill="${c}"/><ellipse cx="600" cy="540" rx="330" ry="70" fill="${c}" opacity=".85"/>`,
  board: (c) => `<rect x="330" y="300" width="540" height="620" rx="40" fill="${c}"/><circle cx="600" cy="370" r="22" fill="#F3F0EA"/>`,
  mug: (c) => `<rect x="400" y="380" width="360" height="400" rx="40" fill="${c}"/><path d="M760 470 h60 a90 90 0 0 1 0 180 h-60z" fill="none" stroke="${c}" stroke-width="44"/>`,
  vase: (c) => `<path d="M520 300 h160 v90 c120 60 140 190 110 300 c-20 90 -90 150 -190 150 c-100 0 -170 -60 -190 -150 c-30 -110 -10 -240 110 -300z" fill="${c}"/>`,
  napkin: (c) => `<rect x="300" y="380" width="600" height="440" rx="24" fill="${c}"/><rect x="300" y="380" width="600" height="110" rx="24" fill="${c}" opacity=".7"/>`,
  throw: (c) => `<rect x="280" y="340" width="640" height="520" rx="30" fill="${c}"/><g stroke="#F3F0EA" stroke-opacity=".4" stroke-width="10">${[0,1,2,3,4].map(i=>`<line x1="280" y1="${420+i*90}" x2="920" y2="${420+i*90}"/>`).join("")}</g>`,
  lamp: (c) => `<path d="M420 560 L520 300 h160 l100 260z" fill="${c}"/><rect x="585" y="560" width="30" height="240" fill="${c}"/><rect x="500" y="800" width="200" height="40" rx="20" fill="${c}"/>`,
  candle: (c) => `<rect x="470" y="420" width="260" height="400" rx="30" fill="${c}"/><rect x="590" y="370" width="20" height="60" rx="10" fill="${c}"/>`,
  basket: (c) => `<path d="M320 480 h560 l-60 360 h-440z" fill="${c}"/><path d="M420 480 c0 -140 360 -140 360 0" fill="none" stroke="${c}" stroke-width="30"/>`,
  box: (c) => `<rect x="330" y="470" width="540" height="340" rx="24" fill="${c}"/><rect x="300" y="400" width="600" height="90" rx="20" fill="${c}" opacity=".8"/>`,
  tray: (c) => `<rect x="260" y="470" width="680" height="300" rx="34" fill="${c}"/><rect x="300" y="510" width="600" height="220" rx="22" fill="#F3F0EA" opacity=".25"/>`,
  hook: (c) => `<rect x="420" y="360" width="360" height="90" rx="20" fill="${c}"/>${[0,1,2].map(i=>`<path d="M${480+i*120} 450 v170 a30 30 0 0 0 60 0" fill="none" stroke="${c}" stroke-width="22"/>`).join("")}`,
}

export const DEMO_IMAGES = [
  ["stoneware-dinner-plate", "plate", 0, 2], ["oak-serving-board", "board", 1, 1], ["ceramic-serving-bowl", "bowl", 2, 3],
  ["ribbed-stoneware-mug", "mug", 3, 0], ["tapered-bud-vase", "vase", 0, 4], ["linen-napkin-set", "napkin", 1, 3],
  ["wool-throw", "throw", 2, 2], ["paper-cone-lamp", "lamp", 3, 1], ["soy-candle", "candle", 0, 3],
  ["seagrass-basket", "basket", 1, 2], ["cedar-storage-box", "box", 2, 1], ["walnut-catch-all-tray", "tray", 3, 0],
  ["wall-hook-rail", "hook", 1, 4], ["cat-tableware", "plate", 0, 1], ["cat-kitchen", "board", 1, 0], ["cat-decor", "vase", 2, 2],
  ["cat-textiles", "throw", 3, 3], ["cat-lighting", "lamp", 0, 0], ["cat-storage", "basket", 1, 1],
]

for (const [name, shape, bg, ink] of DEMO_IMAGES) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200"><rect width="1200" height="1200" fill="${BG[bg]}"/>
    <ellipse cx="600" cy="900" rx="330" ry="40" fill="#000" opacity=".05"/>${shapes[shape](INK[ink])}</svg>`
  const jpg = await sharp(Buffer.from(svg)).jpeg({ quality: 84, mozjpeg: true, progressive: true }).toBuffer()
  writeFileSync(join(out, `${name}.jpg`), jpg)
}
console.log(`${DEMO_IMAGES.length} images → ${out}`)
